# region: intake
def intake(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: render
def render(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs, factor=3):
    return [v * factor for v in xs]

# region: gather
def gather(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(gather(fold(render(intake(raw)))))

